_DISCORD_ICO_B64 = {
    16: "",
    32: "",
    48: "",
    64: "",
    128: "",
    256: "",
}

def _make_discord_icon() -> QIcon:
    icon = QIcon()
    for sz, b64 in _DISCORD_ICO_B64.items():
        px = QPixmap()
        px.loadFromData(__import__('base64').b64decode(b64))
        icon.addPixmap(px)
    return icon

_TOKEN_RE = re.compile(r"[\w-]{24,26}\.[\w-]{6}\.[\w-]{25,38}")
_MFA_RE   = re.compile(r"mfa\.[\w-]{84}")
_TOKEN_STORE: dict[str, str] = {}

def get_token(uid): return _TOKEN_STORE.get(uid, "")
def _hdrs(tok): return {
    "Authorization": tok,
    "Content-Type":  "application/json",
    "User-Agent":    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
}

def _pil_to_qpixmap(img: Image.Image) -> QPixmap:
    buf = io.BytesIO()
    img.save(buf, "PNG")
    buf.seek(0)
    return QPixmap.fromImage(QImage.fromData(buf.read()))

def _aa_circle_pil(img: Image.Image, size: int) -> QPixmap:
    S    = size * 4
    img  = img.resize((S, S), Image.LANCZOS).convert("RGBA")
    mask = Image.new("L", (S, S), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, S-1, S-1), fill=255)
    out  = Image.new("RGBA", (S, S), (0, 0, 0, 0))
    out.paste(img, mask=mask)
    return _pil_to_qpixmap(out.resize((size, size), Image.LANCZOS))

def _initials_pixmap(name: str, size: int) -> QPixmap:
    col = AV_COLS[sum(ord(c) for c in name) % len(AV_COLS)]
    S   = size * 4
    img = Image.new("RGBA", (S, S), (0, 0, 0, 0))
    d   = ImageDraw.Draw(img)
    d.ellipse((0, 0, S-1, S-1), fill=col)
    letter = name[0].upper() if name else "?"
    fnt = None
    for face in ("segoeui.ttf", "arial.ttf", "DejaVuSans.ttf"):
        try: fnt = PILFont.truetype(face, int(S * .42)); break
        except: pass
    if fnt:
        bb = d.textbbox((0, 0), letter, font=fnt)
        tw, th = bb[2]-bb[0], bb[3]-bb[1]
        d.text(((S-tw)/2-bb[0], (S-th)/2-bb[1]), letter, fill="#fff", font=fnt)
    else:
        d.text((S//2-10, S//2-14), letter, fill="#fff")
    mask = Image.new("L", (S, S), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, S-1, S-1), fill=255)
    out  = Image.new("RGBA", (S, S), (0, 0, 0, 0))
    out.paste(img, mask=mask)
    return _pil_to_qpixmap(out.resize((size, size), Image.LANCZOS))

def _fetch_url_pixmap(url: str, size: int) -> QPixmap | None:
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=6) as r:
            data = r.read()
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        return _aa_circle_pil(img, size)
    except:
        return None

def avatar_pixmap(account: dict, size: int) -> QPixmap:
    key = f"_px{size}"
    if key in account and account[key] is not None:
        return account[key]
    url = account.get("avatar_url", "")
    px  = _fetch_url_pixmap(url, size) if url else None
    if px is None:
        uname = account.get("username", "?")
        px    = _initials_pixmap(uname, size)
    account[key] = px
    return px

class NetCheckWorker(QThread):
    result = pyqtSignal(bool)
    def run(self):
        import socket
        for host, port in [("8.8.8.8", 53), ("1.1.1.1", 53), ("9.9.9.9", 53)]:
            try:
                s = socket.create_connection((host, port), timeout=3)
                s.close()
                self.result.emit(True)
                return
            except OSError:
                pass
        self.result.emit(False)

class ScanWorker(QThread):
    found = pyqtSignal(str)
    done  = pyqtSignal(list)

    def run(self):
        global _TOKEN_STORE
        _TOKEN_STORE.clear()
        local = os.getenv("LOCALAPPDATA", "")
        roam  = os.getenv("APPDATA", "")
        paths = [
            os.path.join(roam,  "discord",       "Local Storage", "leveldb"),
            os.path.join(roam,  "discordcanary", "Local Storage", "leveldb"),
            os.path.join(roam,  "discordptb",    "Local Storage", "leveldb"),
            os.path.join(local, "Google","Chrome","User Data","Default","Local Storage","leveldb"),
            os.path.join(local, "Microsoft","Edge","User Data","Default","Local Storage","leveldb"),
            os.path.join(local, "BraveSoftware","Brave-Browser","User Data","Default","Local Storage","leveldb"),
        ]
        candidates: set = set()
        for p in paths:
            if not os.path.exists(p): continue
            for fn in os.listdir(p):
                if not (fn.endswith(".log") or fn.endswith(".ldb")): continue
                try:
                    with open(os.path.join(p, fn), "r", errors="ignore") as f:
                        c = f.read()
                    for m in _TOKEN_RE.finditer(c): candidates.add(m.group())
                    for m in _MFA_RE.finditer(c):   candidates.add(m.group())
                except: pass

        seen, accounts = set(), []
        for tok in candidates:
            try:
                r = requests.get(f"{BASE}/users/@me", headers=_hdrs(tok), timeout=6)
                if r.status_code != 200: continue
                info = r.json()
                uid  = info.get("id", "")
                if not uid or uid in seen: continue
                seen.add(uid)
                _TOKEN_STORE[uid] = tok
                uname  = info.get("username", "Unknown")
                avid   = info.get("avatar", "")
                av_url = (f"{CDN}/avatars/{uid}/{avid}.{'gif' if avid.startswith('a_') else 'png'}?size=80"
                          if avid else "")
                accounts.append({"id": uid, "username": uname, "avatar_url": av_url})
                self.found.emit(uname)
            except: pass
        self.done.emit(accounts)

class AvatarLoader(QThread):
    loaded = pyqtSignal(int, object)

    def __init__(self, items: list, size: int):
        super().__init__()
        self.items = items
        self.size  = size

    def run(self):
        for i, item in enumerate(self.items):
            px = avatar_pixmap(item, self.size)
            self.loaded.emit(i, px)

class DMLoader(QThread):
    done  = pyqtSignal(list)
    error = pyqtSignal(str)

    def __init__(self, account_id):
        super().__init__()
        self.aid = account_id

    def run(self):
        tok = get_token(self.aid)
        if not tok:
            self.error.emit("No token found for account.")
            self.done.emit([]); return
        try:
            r = requests.get(f"{BASE}/users/@me/channels",
                             headers=_hdrs(tok), timeout=10)
            if r.status_code != 200:
                self.error.emit(f"API error {r.status_code} loading channels.")
                self.done.emit([]); return
            results = []
            for ch in r.json():
                if ch.get("type") != 1: continue
                recips = ch.get("recipients", [])
                if not recips: continue
                u    = recips[0]
                name = u.get("username", "Unknown")
                avid = u.get("avatar", ""); uid2 = u.get("id", "")
                av_url = (f"{CDN}/avatars/{uid2}/{avid}.{'gif' if avid.startswith('a_') else 'png'}?size=80"
                          if avid and uid2 else "")
                dm = {"id": ch["id"], "name": name, "avatar_url": av_url}
                px = _fetch_url_pixmap(av_url, 36) if av_url else None
                if px is None:
                    px = _initials_pixmap(name, 36)
                results.append((dm, px))
            self.done.emit(results)
        except Exception as ex:
            self.error.emit(f"Exception in DMLoader: {ex}")
            self.done.emit([])

class PurgeWorker(QThread):
    log     = pyqtSignal(str, str)
    deleted = pyqtSignal(int)
    done    = pyqtSignal(int)

    def __init__(self, aid, channels, delay):
        super().__init__()
        self.aid = aid; self.channels = channels
        self.delay = delay; self._stop = False

    def stop(self): self._stop = True

    def run(self):
        tok = get_token(self.aid)
        if not tok: self.done.emit(0); return
        try:
            me_id = requests.get(f"{BASE}/users/@me",
                                 headers=_hdrs(tok), timeout=6).json()["id"]
        except: self.done.emit(0); return
        total = 0
        for ch_id, ch_name in self.channels:
            if self._stop: break
            self.log.emit(f"━━  Purging DM with {ch_name}…", "inf")
            before = None
            while not self._stop:
                params = {"limit": 100}
                if before: params["before"] = before
                try:
                    r = requests.get(f"{BASE}/channels/{ch_id}/messages",
                                     headers=_hdrs(tok), params=params, timeout=10)
                except: break
                if r.status_code == 429:
                    w = r.json().get("retry_after", 2)
                    self.log.emit(f"⚠  Rate limited {w:.1f}s", "wrn"); time.sleep(w); continue
                if r.status_code != 200:
                    self.log.emit(f"✗  Fetch failed ({r.status_code})", "err"); break
                msgs = r.json()
                if not msgs: self.log.emit(f"✓  {ch_name} — done.", "ok"); break
                mine   = [m for m in msgs if m["author"]["id"] == me_id]
                before = msgs[-1]["id"]
                if not mine:
                    if len(msgs) < 100: self.log.emit(f"✓  {ch_name} — start.", "ok"); break
                    continue
                for msg in mine:
                    if self._stop: break
                    try:
                        d = requests.delete(
                            f"{BASE}/channels/{ch_id}/messages/{msg['id']}",
                            headers=_hdrs(tok), timeout=10)
                    except: continue
                    if d.status_code == 204:
                        total += 1
                        self.log.emit(
                            f"🗑  [{total}]  {(msg.get('content') or '[attachment]')[:60]}", "ok")
                        self.deleted.emit(total)
                    elif d.status_code == 429:
                        w = d.json().get("retry_after", 2)
                        self.log.emit(f"⚠  Rate limited {w:.1f}s","wrn"); time.sleep(w)
                    elif d.status_code == 404:
                        self.log.emit("⚠  Already gone.", "dim")
                    time.sleep(self.delay)
        self.done.emit(total)

class AvatarLabel(QLabel):
    def __init__(self, size=40, parent=None):
        super().__init__(parent)
        self._sz  = size
        self._pix = None
        self.setFixedSize(size, size)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)

    def set_pixmap(self, px: QPixmap):
        if px:
            self._pix = px.scaled(self._sz, self._sz,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation)
        else:
            self._pix = None
        self.update()

    def paintEvent(self, _):
        if not self._pix: return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        path = QPainterPath()
        path.addEllipse(0, 0, float(self._sz), float(self._sz))
        p.setClipPath(path)
        p.drawPixmap(0, 0, self._pix)
        p.end()

class AnimatedBtn(QPushButton):
    def __init__(self, text, bg, bg_h, fg="#ffffff",
                 radius=9, h=36, parent=None):
        super().__init__(text, parent)
        self._bg  = QColor(bg); self._bgh = QColor(bg_h)
        self._fg  = fg; self._r = radius
        self._cur = QColor(bg)
        self.setFixedHeight(h)
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
        self.setFont(QFont("Segoe UI", 10))
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)

        self._anim = QPropertyAnimation(self, b"_anim_color", self)
        self._anim.setDuration(140)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

    def _get_col(self): return self._cur
    def _set_col(self, c):
        self._cur = c
        self.update()
    _anim_color = pyqtProperty(QColor, _get_col, _set_col)

    def enterEvent(self, e):
        if self.isEnabled(): self._fade(self._bgh)
    def leaveEvent(self, e):
        if self.isEnabled(): self._fade(self._bg)
    def _fade(self, target):
        self._anim.stop()
        self._anim.setStartValue(self._cur)
        self._anim.setEndValue(target)
        self._anim.start()

    def setEnabled(self, v):
        super().setEnabled(v)
        self._cur = self._bg if v else QColor(P["tag"])
        self.update()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        col = self._cur if self.isEnabled() else QColor(P["tag"])
        p.setBrush(QBrush(col))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawRoundedRect(self.rect(), self._r, self._r)
        p.setPen(QColor(P["muted"] if not self.isEnabled() else self._fg))
        p.setFont(self.font())
        p.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, self.text())
        p.end()

    def sizeHint(self):
        fm = QFontMetrics(self.font())
        return QSize(fm.horizontalAdvance(self.text()) + 36, self.height())

class SmoothScrollArea(QScrollArea):
    def __init__(self, parent=None):
        super().__init__(parent)
        self._anim = QPropertyAnimation(self.verticalScrollBar(), b"value")
        self._anim.setDuration(300)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

    def wheelEvent(self, e):
        delta   = e.angleDelta().y()
        current = self.verticalScrollBar().value()
        target  = current - int(delta * 0.8)
        target  = max(self.verticalScrollBar().minimum(),
                      min(self.verticalScrollBar().maximum(), target))
        self._anim.stop()
        self._anim.setStartValue(current)
        self._anim.setEndValue(target)
        self._anim.start()
        e.accept()

class DMCard(QWidget):
    clicked = pyqtSignal(object)

    def __init__(self, dm: dict, px: QPixmap = None, parent=None):
        super().__init__(parent)
        self.dm       = dm
        self.checked  = False
        self._hovered = False
        self._col     = QColor(P["card"])
        self.setFixedHeight(60)
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))
        self.setAttribute(Qt.WidgetAttribute.WA_Hover)

        self._anim = QPropertyAnimation(self, b"_bg_color")
        self._anim.setDuration(130)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(12, 0, 12, 0)
        lay.setSpacing(10)

        self._chk_lbl = QLabel()
        self._chk_lbl.setFixedSize(20, 20)
        self._chk_lbl.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        lay.addWidget(self._chk_lbl)

        self._av = AvatarLabel(36)
        lay.addWidget(self._av)

        txt = QWidget()
        txt.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        tl  = QVBoxLayout(txt)
        tl.setContentsMargins(0, 0, 0, 0)
        tl.setSpacing(1)
        self._name = QLabel(dm["name"])
        self._name.setFont(QFont("Segoe UI", 10, QFont.Weight.DemiBold))
        self._name.setStyleSheet(f"color: {P['text']};")
        self._sub  = QLabel("Direct Message")
        self._sub.setFont(QFont("Segoe UI", 8))
        self._sub.setStyleSheet(f"color: {P['muted']};")
        tl.addWidget(self._name)
        tl.addWidget(self._sub)
        lay.addWidget(txt, 1)

        self._draw_chk(False)
        if px is not None:
            self._av.set_pixmap(px)

    def set_avatar(self, px: QPixmap):
        self._av.set_pixmap(px)

    def _get_bg(self): return self._col
    def _set_bg(self, c): self._col = c; self.update()
    _bg_color = pyqtProperty(QColor, _get_bg, _set_bg)

    def _target_color(self):
        if self.checked:  return QColor(P["card_sel"])
        if self._hovered: return QColor(P["card_hov"])
        return QColor(P["card"])

    def _animate_to(self, col: QColor):
        self._anim.stop()
        self._anim.setStartValue(self._col)
        self._anim.setEndValue(col)
        self._anim.start()

    def _draw_chk(self, checked: bool):
        sz  = 20
        px  = QPixmap(sz, sz)
        px.fill(Qt.GlobalColor.transparent)
        p   = QPainter(px)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        if checked:
            p.setBrush(QBrush(QColor(P["accent"])))
            p.setPen(Qt.PenStyle.NoPen)
            p.drawRoundedRect(0, 0, sz, sz, 6, 6)
            pen = QPen(QColor("#fff"), 2.2)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
            p.setPen(pen)
            p.drawLine(5, 10, 8, 14)
            p.drawLine(8, 14, 15, 6)
        else:
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(P["border"]), 1.5))
            p.drawRoundedRect(1, 1, sz-2, sz-2, 5, 5)
        p.end()
        self._chk_lbl.setPixmap(px)

    def set_checked(self, v: bool):
        self.checked = v
        self._draw_chk(v)
        self._name.setStyleSheet(
            f"color: {P['white'] if v else P['text']};")
        self._animate_to(self._target_color())

    def enterEvent(self, e):
        self._hovered = True
        if not self.checked: self._animate_to(QColor(P["card_hov"]))
    def leaveEvent(self, e):
        self._hovered = False
        if not self.checked: self._animate_to(QColor(P["card"]))
    def mousePressEvent(self, _):
        self.clicked.emit(self)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setBrush(QBrush(self._col))
        pen = QPen(QColor(P["accent"] if self.checked else P["border"]), 1)
        p.setPen(pen)
        p.drawRoundedRect(self.rect().adjusted(1,1,-1,-1), 10, 10)
        p.end()
        super().paintEvent(_)

class AccountRow(QWidget):
    clicked = pyqtSignal(dict)

    def __init__(self, account, selected=False, parent=None):
        super().__init__(parent)
        self.account  = account
        self._sel     = selected
        self._col     = QColor(P["card_sel"] if selected else P["drop_bg"])
        self.setFixedHeight(52)
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))

        self._anim = QPropertyAnimation(self, b"_bg_color")
        self._anim.setDuration(120)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(10, 0, 10, 0)
        lay.setSpacing(10)

        self._av = AvatarLabel(34)
        lay.addWidget(self._av)

        self._lbl = QLabel(account["username"])
        self._lbl.setFont(QFont("Segoe UI", 10, QFont.Weight.DemiBold))
        self._lbl.setStyleSheet(f"color: {P['white']};")
        self._lbl.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        lay.addWidget(self._lbl, 1)

        if selected:
            ck = QLabel("✓")
            ck.setFont(QFont("Segoe UI", 11))
            ck.setStyleSheet(f"color: {P['accent']};")
            ck.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
            lay.addWidget(ck)

        QTimer.singleShot(0, lambda: self._av.set_pixmap(avatar_pixmap(account, 34)))

    def _get_bg(self): return self._col
    def _set_bg(self, c): self._col = c; self.update()
    _bg_color = pyqtProperty(QColor, _get_bg, _set_bg)

    def enterEvent(self, e):
        self._anim.stop()
        self._anim.setStartValue(self._col)
        self._anim.setEndValue(QColor(P["card_sel"]))
        self._anim.start()
    def leaveEvent(self, e):
        if not self._sel:
            self._anim.stop()
            self._anim.setStartValue(self._col)
            self._anim.setEndValue(QColor(P["drop_bg"]))
            self._anim.start()
    def mousePressEvent(self, _): self.clicked.emit(self.account)

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setBrush(QBrush(self._col))
        p.setPen(Qt.PenStyle.NoPen)
        p.drawRoundedRect(self.rect().adjusted(2,2,-2,-2), 8, 8)
        p.end()
        super().paintEvent(_)

class AccountDropdown(QWidget):
    account_selected = pyqtSignal(dict)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.accounts: list[dict] = []
        self._sel: dict | None    = None
        self._popup: QWidget | None = None
        self.setFixedHeight(52)
        self.setCursor(QCursor(Qt.CursorShape.PointingHandCursor))

        self._col  = QColor(P["inp"])
        self._anim = QPropertyAnimation(self, b"_bg_color")
        self._anim.setDuration(130)
        self._anim.setEasingCurve(QEasingCurve.Type.OutCubic)

        lay = QHBoxLayout(self)
        lay.setContentsMargins(12, 6, 12, 6)
        lay.setSpacing(10)

        self._av  = AvatarLabel(34)
        lay.addWidget(self._av)

        self._lbl = QLabel("Scanning for accounts…")
        self._lbl.setFont(QFont("Segoe UI", 10, QFont.Weight.DemiBold))
        self._lbl.setStyleSheet(f"color: {P['muted']};")
        self._lbl.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        lay.addWidget(self._lbl, 1)

        self._chev = QLabel("▾")
        self._chev.setFont(QFont("Segoe UI", 11))
        self._chev.setStyleSheet(f"color: {P['muted']};")
        self._chev.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        lay.addWidget(self._chev)

    def _get_bg(self): return self._col
    def _set_bg(self, c): self._col = c; self.update()
    _bg_color = pyqtProperty(QColor, _get_bg, _set_bg)

    def enterEvent(self, e):
        self._anim.stop()
        self._anim.setStartValue(self._col)
        self._anim.setEndValue(QColor(P["card_hov"]))
        self._anim.start()
    def leaveEvent(self, e):
        self._anim.stop()
        self._anim.setStartValue(self._col)
        self._anim.setEndValue(QColor(P["inp"]))
        self._anim.start()

    def paintEvent(self, _):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setBrush(QBrush(self._col))
        p.setPen(QPen(QColor(P["border"]), 1))
        p.drawRoundedRect(self.rect().adjusted(1,1,-1,-1), 10, 10)
        p.end()
        super().paintEvent(_)

    def set_accounts(self, accounts):
        self.accounts = accounts
        if accounts: self._pick(accounts[0], emit=False)

    def _pick(self, account, emit=True):
        self._sel = account
        self._lbl.setText(account["username"])
        self._lbl.setStyleSheet(f"color: {P['white']};")
        self._av.set_pixmap(avatar_pixmap(account, 34))
        if emit: self.account_selected.emit(account)

    def selected(self): return self._sel

    def mousePressEvent(self, _):
        if not self.accounts: return
        if self._popup and self._popup.isVisible():
            self._close_popup()
        else:
            self._open_popup()

    def _open_popup(self):
        popup = QWidget(self.window(), Qt.WindowType.Popup)
        popup.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)

        outer = QWidget(popup)
        outer.setObjectName("pop")
        outer.setStyleSheet(f"""
            QWidget
                background: {P['drop_bg']};
                border: 1px solid {P['border']};
                border-radius: 12px;
            }}
        """)
        ol = QVBoxLayout(outer)
        ol.setContentsMargins(0, 0, 0, 0)
        ol.setSpacing(0)

        rows_w = QWidget()
        rows_w.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        rl = QVBoxLayout(rows_w)
        rl.setContentsMargins(6, 6, 6, 6)
        rl.setSpacing(2)
        for acc in self.accounts:
            row = AccountRow(acc, selected=(self._sel and acc["id"]==self._sel["id"]))
            row.clicked.connect(self._row_clicked)
            rl.addWidget(row)
        ol.addWidget(rows_w)

        pl = QVBoxLayout(popup)
        pl.setContentsMargins(0, 0, 0, 0)
        pl.addWidget(outer)

        gpos = self.mapToGlobal(QPoint(0, self.height() + 4))
        popup.move(gpos)
        popup.setFixedWidth(self.width())
        popup.adjustSize()

        eff  = QGraphicsOpacityEffect(popup)
        popup.setGraphicsEffect(eff)
        anim = QPropertyAnimation(eff, b"opacity", popup)
        anim.setDuration(160)
        anim.setStartValue(0.0); anim.setEndValue(1.0)
        anim.setEasingCurve(QEasingCurve.Type.OutCubic)
        anim.start(QAbstractAnimation.DeletionPolicy.DeleteWhenStopped)

        popup.show()
        self._popup  = popup
        self._chev.setText("▴")

    def _row_clicked(self, account):
        self._pick(account)
        self._close_popup()

    def _close_popup(self):
        if not self._popup: return
        p    = self._popup
        self._popup = None
        eff  = QGraphicsOpacityEffect(p)
        p.setGraphicsEffect(eff)
        anim = QPropertyAnimation(eff, b"opacity", p)
        anim.setDuration(100)
        anim.setStartValue(1.0); anim.setEndValue(0.0)
        anim.finished.connect(p.close)
        anim.start(QAbstractAnimation.DeletionPolicy.DeleteWhenStopped)
        self._chev.setText("▾")

